import { createHash } from "node:crypto"
import fs from "node:fs"

import { expanduser, isFile, isLink, pyJoin, realpath } from "../../../lib/measurekit/pypath.ts"
import { compilePythonRegex } from "../../../lib/measurekit/pyregex.ts"
import { firstLineOf, readBytes } from "../../../lib/measurekit/pyio.ts"

export const GENERATED_CLAUDE_MD_HEADER =
  "<!-- GENERATED by keel bin/link from PRINCIPLES.md + PERSONAL.md. " +
  "Edit the sources, then run bin/link --write. -->"
const V1_BASELINE_SUFFIX = "-v1baseline"
const PROJECT_SLUG_CHARS = compilePythonRegex("[^A-Za-z0-9]", "g")

export function cliConfigDir(): string {
  return process.env["CLAUDE_CONFIG_DIR"] || expanduser("~/.claude")
}

export function isKeelLive(configDir: string, keelHome: string, skill: string): boolean {
  const skillLink = pyJoin(configDir, "skills", skill)
  return linksInto(skillLink, keelHome) && isGenerated(pyJoin(configDir, "CLAUDE.md"))
}

export function suiteEvalId(evalId: string, keelLive: boolean): string {
  return keelLive ? evalId : evalId + V1_BASELINE_SUFFIX
}

export function configFingerprint(configDir: string, skill: string): { claude_md_sha256: string | null; skill_md_sha256: string | null } {
  return {
    claude_md_sha256: sha256(pyJoin(configDir, "CLAUDE.md")),
    skill_md_sha256: sha256(pyJoin(configDir, "skills", skill, "SKILL.md")),
  }
}

export function projectDirFor(cwd: string, configDir: string): string {
  return pyJoin(configDir, "projects", realpath(cwd).replace(PROJECT_SLUG_CHARS, "-"))
}

function linksInto(path: string, root: string): boolean {
  if (!isLink(path)) return false
  const pointee = realpath(path)
  const realRoot = realpath(root)
  return pointee === realRoot || pointee.startsWith(realRoot + "/")
}

function isGenerated(path: string): boolean {
  if (isLink(path) || !isFile(path)) return false
  return firstLineOf(readBytes(path)).replace(/\n$/, "") === GENERATED_CLAUDE_MD_HEADER
}

function sha256(path: string): string | null {
  if (!isFile(path)) return null
  return createHash("sha256").update(fs.readFileSync(path)).digest("hex")
}
